704	  async function resolveActiveIssueRun(issue: {
705	    id: string;
706	    assigneeAgentId: string | null;
707	    executionRunId?: string | null;
708	  }) {
709	    let runToInterrupt = issue.executionRunId ? await heartbeat.getRun(issue.executionRunId) : null;
710	
711	    if ((!runToInterrupt || runToInterrupt.status !== "running") && issue.assigneeAgentId) {
712	      const activeRun = await heartbeat.getActiveRunForAgent(issue.assigneeAgentId);
713	      const activeIssueId =
714	        activeRun &&
715	        activeRun.contextSnapshot &&
716	        typeof activeRun.contextSnapshot === "object" &&
717	        typeof (activeRun.contextSnapshot as Record<string, unknown>).issueId === "string"
718	          ? ((activeRun.contextSnapshot as Record<string, unknown>).issueId as string)
719	          : null;
720	      if (activeRun && activeRun.status === "running" && activeIssueId === issue.id) {
721	        runToInterrupt = activeRun;
722	      }
723	    }
724	
725	    return runToInterrupt?.status === "running" ? runToInterrupt : null;
726	  }
