756	  function isQueuedIssueCommentForActiveRun(params: {
757	    comment: {
758	      authorAgentId?: string | null;
759	      createdAt?: Date | string | null;
760	    };
761	    activeRun: {
762	      agentId?: string | null;
763	      startedAt?: Date | string | null;
764	      createdAt?: Date | string | null;
765	    };
766	  }) {
767	    const activeRunStartedAtMs =
768	      toValidTimestamp(params.activeRun.startedAt) ?? toValidTimestamp(params.activeRun.createdAt);
769	    const commentCreatedAtMs = toValidTimestamp(params.comment.createdAt);
770	
771	    if (activeRunStartedAtMs === null || commentCreatedAtMs === null) return false;
772	    if (params.comment.authorAgentId && params.comment.authorAgentId === params.activeRun.agentId) return false;
773	    return commentCreatedAtMs >= activeRunStartedAtMs;
774	  }
